<?php
declare(strict_types=1);
namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\BouquetRepository;use App\Security\Auth;use App\Services\BouquetService;use Throwable;
final readonly class BouquetController{public function __construct(private View $view,private BouquetRepository $repo,private BouquetService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('bouquets/index',['title'=>'Bouquets','bouquets'=>$this->repo->all(),'categories'=>$this->repo->categories(),'map'=>$this->repo->map(),'csrf'=>$this->csrf]);}public function save(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->save($r->input));}public function toggle(Request $r):void{$this->allow();$this->attempt(fn()=>$this->service->toggle($r->int('id')));}private function attempt(callable $f):never{try{$f();Response::redirect('/bouquets');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('bouquets.manage')){http_response_code(403);exit('Sin permiso');}}}
